/* @lc app=leetcode id=3624 lang=kotlin */ class Solution { fun dp(x: Long): Int = generateSequence(x to 0) { (v, c) -> if (v == 1L) null else java.lang.Long.bitCount(v).toLong() to c + 1 }.last().second fun ad(t: IntArray, i0: Int, d: Int) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] += d } fun qs(t: IntArray, i0: Int): Int = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun popcountDepth(nums: LongArray, queries: Array<LongArray>): IntArray = nums.size.let { n -> Array(6) { IntArray(n + 1) }.let { bit -> nums.indices.forEach { i -> ad(bit[dp(nums[i])], i + 1, 1) }.let { queries.mapNotNull { q -> if (q[0] == 1L) (if (q[3] > 5) 0 else qs(bit[q[3].toInt()], q[2].toInt() + 1) - qs(bit[q[3].toInt()], q[1].toInt())) else ad(bit[dp(nums[q[1].toInt()])], q[1].toInt() + 1, -1).also { nums[q[1].toInt()] = q[2] }.also { ad(bit[dp(q[2])], q[1].toInt() + 1, 1) }.let { null } }.toIntArray() } } } }